package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Any problem with the file (unreadable, missing required keys, unknown keys, malformed or out-of-range
 * values) makes {@link #load} throw a {@link ConfigException} that lists every problem found. Defaults apply only
 * to optional keys that are absent, never to values that are present but wrong.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    static final String UPSTREAM_URL = "upstream.url";
    static final String API_TOKEN = "api.token";
    static final String WORKER_THREADS = "worker.threads";
    static final String QUEUE_CAPACITY = "queue.capacity";
    static final String RETRY_MAX_ATTEMPTS = "retry.max-attempts";
    static final String REQUEST_TIMEOUT = "request.timeout";
    static final String METRICS_ENABLED = "metrics.enabled";

    private static final Set<String> KNOWN_KEYS = Set.of(
            UPSTREAM_URL, API_TOKEN, WORKER_THREADS, QUEUE_CAPACITY, RETRY_MAX_ATTEMPTS, REQUEST_TIMEOUT,
            METRICS_ENABLED);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();

        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add(key + ": unknown key (expected one of " + new TreeSet<>(KNOWN_KEYS) + ")");
            }
        }

        URI upstream = uri(properties, problems);
        String apiToken = required(properties, API_TOKEN, problems);
        int workerThreads = intValue(properties, WORKER_THREADS, DEFAULT_WORKER_THREADS, 1, problems);
        int queueCapacity = intValue(properties, QUEUE_CAPACITY, DEFAULT_QUEUE_CAPACITY, 1, problems);
        int retryAttempts = intValue(properties, RETRY_MAX_ATTEMPTS, DEFAULT_RETRY_ATTEMPTS, 0, problems);
        Duration requestTimeout = duration(properties, problems);
        boolean metricsEnabled = booleanValue(properties, METRICS_ENABLED, problems);

        if (!problems.isEmpty()) {
            throw new ConfigException(file, problems);
        }
        return new ServiceConfig(
                upstream, apiToken, workerThreads, queueCapacity, retryAttempts, requestTimeout, metricsEnabled);
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException(file, List.of("cannot read the file: " + describe(e)));
        }
        return properties;
    }

    private static String describe(Exception e) {
        if (e instanceof java.nio.file.NoSuchFileException) {
            return "file not found";
        }
        return e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName();
    }

    private static String required(Properties properties, String key, List<String> problems) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + ": is required");
            return null;
        }
        return value.trim();
    }

    private static URI uri(Properties properties, List<String> problems) {
        String raw = required(properties, UPSTREAM_URL, problems);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            String scheme = uri.getScheme();
            if (scheme == null
                    || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))
                    || uri.getHost() == null) {
                problems.add(UPSTREAM_URL + ": '" + raw + "' is not an absolute http(s) URL");
                return null;
            }
            return uri;
        } catch (URISyntaxException e) {
            problems.add(UPSTREAM_URL + ": '" + raw + "' is not a valid URL (" + e.getReason() + ")");
            return null;
        }
    }

    private static int intValue(
            Properties properties, String key, int defaultValue, int minimum, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        String trimmed = raw.trim();
        int value;
        try {
            value = Integer.parseInt(trimmed);
        } catch (NumberFormatException e) {
            problems.add(key + ": '" + trimmed + "' is not a whole number");
            return defaultValue;
        }
        if (value < minimum) {
            problems.add(key + ": " + value + " is too small, must be at least " + minimum);
            return defaultValue;
        }
        return value;
    }

    private static Duration duration(Properties properties, List<String> problems) {
        String raw = properties.getProperty(REQUEST_TIMEOUT);
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        String trimmed = raw.trim();
        Matcher matcher = DURATION.matcher(trimmed);
        if (!matcher.matches()) {
            problems.add(REQUEST_TIMEOUT + ": '" + trimmed
                    + "' is not a duration, expected a whole number followed by ms, s or m (for example 30s)");
            return DEFAULT_REQUEST_TIMEOUT;
        }
        Duration value;
        try {
            long amount = Long.parseLong(matcher.group(1));
            value = switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        } catch (ArithmeticException | NumberFormatException e) {
            problems.add(REQUEST_TIMEOUT + ": '" + trimmed + "' is too large");
            return DEFAULT_REQUEST_TIMEOUT;
        }
        if (value.isZero()) {
            problems.add(REQUEST_TIMEOUT + ": must be greater than zero");
            return DEFAULT_REQUEST_TIMEOUT;
        }
        return value;
    }

    private static boolean booleanValue(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String trimmed = raw.trim();
        if (trimmed.equalsIgnoreCase("true")) {
            return true;
        }
        if (!trimmed.equalsIgnoreCase("false")) {
            problems.add(key + ": '" + trimmed + "' must be true or false");
        }
        return false;
    }
}

