package com.acme.relay;

import com.acme.relay.config.ConfigException;
import com.acme.relay.config.ConfigLoader;
import com.acme.relay.config.ServiceConfig;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;

public final class Main {
    private static final String DEFAULT_CONFIG_FILE = "config.properties";

    /** Exit status when the relay refuses to start because of its configuration. */
    static final int EXIT_CONFIG_ERROR = 2;

    private Main() {}

    public static void main(String[] args) throws IOException, InterruptedException {
        int status = run(args, System.in, System.out, System.err);
        if (status != 0) {
            System.exit(status);
        }
    }

    static int run(String[] args, InputStream in, PrintStream out, PrintStream err)
            throws IOException, InterruptedException {
        Path configFile = Path.of(args.length > 0 ? args[0] : DEFAULT_CONFIG_FILE);
        ServiceConfig config;
        try {
            config = ConfigLoader.load(configFile);
        } catch (ConfigException e) {
            err.println("relay: refusing to start, " + e.getMessage());
            return EXIT_CONFIG_ERROR;
        }
        Relay relay = new Relay(config, new ConsoleUplink(config, out), err);
        try (BufferedReader input = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = input.readLine()) != null) {
                relay.submit(line);
            }
        }
        relay.shutdown();
        return 0;
    }
}

