@Test
void acceptsBooleanInAnyCaseAndSurroundingWhitespace() throws IOException {
    ServiceConfig config = ConfigLoader.load(write(REQUIRED + "metrics.enabled=TRUE  \nworker.threads=6 \n"));

    assertTrue(config.metricsEnabled());
    assertEquals(6, config.workerThreads());
