// Regression: a typo'd worker count ("1O" with a letter O) used to fall back to the default silently.
@Test
void rejectsWorkerCountContainingALetter() throws IOException {
    assertRejected(REQUIRED + "worker.threads=1O\n", "worker.threads", "'1O'");
}

@Test
void rejectsNonNumericIntegers() throws IOException {
    assertRejected(REQUIRED + "worker.threads=four\n", "worker.threads", "'four'");
    assertRejected(REQUIRED + "queue.capacity=1k\n", "queue.capacity", "'1k'");
    assertRejected(REQUIRED + "retry.max-attempts=\n", "retry.max-attempts");
    assertRejected(REQUIRED + "queue.capacity=99999999999\n", "queue.capacity");
}

@Test
void rejectsIntegersBelowTheirMinimum() throws IOException {
    assertRejected(REQUIRED + "worker.threads=0\n", "worker.threads", "at least 1");
    assertRejected(REQUIRED + "queue.capacity=-5\n", "queue.capacity", "at least 1");
    assertRejected(REQUIRED + "retry.max-attempts=-1\n", "retry.max-attempts", "at least 0");
}

@Test
void acceptsZeroRetries() throws IOException {
    assertEquals(0, ConfigLoader.load(write(REQUIRED + "retry.max-attempts=0\n")).retryAttempts());
}

@Test
void rejectsTimeoutWithoutAUnit() throws IOException {
    assertRejected(REQUIRED + "request.timeout=30\n", "request.timeout", "'30'");
}

@Test
void rejectsMalformedZeroAndOversizedTimeouts() throws IOException {
    assertRejected(REQUIRED + "request.timeout=30sec\n", "request.timeout");
    assertRejected(REQUIRED + "request.timeout=0s\n", "request.timeout", "greater than zero");
    assertRejected(REQUIRED + "request.timeout=99999999999999999999m\n", "request.timeout", "too large");
}

@Test
void rejectsBooleansOtherThanTrueOrFalse() throws IOException {
    assertRejected(REQUIRED + "metrics.enabled=yes\n", "metrics.enabled", "'yes'");
    assertRejected(REQUIRED + "metrics.enabled=ture\n", "metrics.enabled", "'ture'");
}

@Test
void upstreamUrlIsRequired() throws IOException {
    assertRejected("api.token=s3cret\n", "upstream.url", "required");
}

@Test
void rejectsInvalidUpstreamUrls() throws IOException {
    assertRejected("api.token=s3cret\nupstream.url=uplink.example.com/v1\n", "upstream.url");
    assertRejected("api.token=s3cret\nupstream.url=https://bad host/\n", "upstream.url");
    assertRejected("api.token=s3cret\nupstream.url=ftp://uplink.example.com/\n", "upstream.url");
}

@Test
void rejectsUnknownKeysSuchAsMisspelledOnes() throws IOException {
    assertRejected(REQUIRED + "worker.thread=8\n", "worker.thread:", "unknown key");
}

@Test
void reportsEveryProblemAtOnce() throws IOException {
    Path file = write("upstream.url=https://uplink.example.com/v1/events\n"
            + "worker.threads=x\nrequest.timeout=5\nmetrics.enabled=maybe\n");

    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

    assertEquals(4, error.problems().size(), error.getMessage());
    for (String key : new String[] {"api.token", "worker.threads", "request.timeout", "metrics.enabled"}) {
        assertTrue(error.getMessage().contains(key), error.getMessage());
    }
    assertTrue(error.getMessage().contains(file.toString()), error.getMessage());
}

@Test
void rejectsAMissingFileInsteadOfRunningOnDefaults() {
    Path missing = dir.resolve("does-not-exist.properties");

    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(missing));

    assertTrue(error.getMessage().contains("file not found"), error.getMessage());
    assertTrue(error.getMessage().contains(missing.toString()), error.getMessage());
}

private void assertRejected(String content, String... expectedFragments) throws IOException {
    Path file = write(content);
    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));
    for (String fragment : expectedFragments) {
        assertTrue(error.getMessage().contains(fragment), error.getMessage());
    }
}

